    TopModule dut (
        .in  (in),
        .sel (sel),
        .out (out)
    );

    integer errors = 0;
    integer i;
    reg [3:0] expected;

    initial begin
        // Initialize inputs to avoid X/Z propagation during unselected checks
        in = 1024'h0;
        sel = 8'h0;
        #10;

        // Test 1: Populate input with a known pattern where each 4-bit chunk 
        // contains its own index value (modulo 16) to uniquely identify chunks.
        for (i = 0; i < 256; i = i + 1) begin
            in[i*4 +: 4] = i[3:0];
        end
        #10;

        // Verify a representative sample of indices (corners, midpoints, full range)
        // Check sel = 0 (lower bounds)
        sel = 8'd0;
        #5;
        expected = in[sel*4 +: 4];
        if (out !== expected) errors = errors + 1;

        // Check sel = 1
        sel = 8'd1;
        #5;
        expected = in[sel*4 +: 4];
        if (out !== expected) errors = errors + 1;

        // Check sel = 127 (midpoint)
        sel = 8'd127;
        #5;
        expected = in[sel*4 +: 4];
        if (out !== expected) errors = errors + 1;

        // Check sel = 255 (upper bound / maximum index)
        sel = 8'd255;
        #5;
        expected = in[sel*4 +: 4];
        if (out !== expected) errors = errors + 1;

        // Test 2: Random/alternating bit patterns across the whole range
        in = 1024'hFEDCBA9876543210FEDCBA9876543210FEDCBA9876543210FEDCBA9876543210; // repeated pattern
        // Let's test a loop of 16 specific selections
        for (i = 0; i < 16; i = i + 1) begin
            sel = i[7:0];
            #5;
            expected = in[sel*4 +: 4];
            if (out !== expected) begin
                errors = errors + 1;
            end
        end

        // Test 3: Check boundary condition where sel = 255 (topmost 4 bits: bits [1023:1020])
        in = 1024'h0;
        in[1023:1020] = 4'b1111;
        sel = 8'd255;
        #5;
        if (out !== 4'b1111) errors = errors + 1;

        // Final result evaluation
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
